package com.revivex.api;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import com.revivex.domain.*; import com.revivex.repository.*; import com.revivex.service.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/v1") @CrossOrigin(origins="*") public class RecoveryController { private final RecoveryService service; private final AuditService audit; private final RecoveryCaseRepository cases; private final MerchantPolicyRepository policies; private final RecoveryActionRepository actions; private final WebhookEventRepository webhooks; private final WebhookSecurity webhookSecurity; private final ObjectMapper mapper=new ObjectMapper(); public RecoveryController(RecoveryService s,AuditService a,RecoveryCaseRepository c,MerchantPolicyRepository p,RecoveryActionRepository ra,WebhookEventRepository w,WebhookSecurity ws){service=s;audit=a;cases=c;policies=p;actions=ra;webhooks=w;webhookSecurity=ws;}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","service","ReviveX","mode",service.status().get("mode"));}
 @GetMapping("/system/status") public Map<String,Object> status(){return service.status();}
 @GetMapping("/recovery/cases") public List<RecoveryCase> all(){return service.all();} @GetMapping("/recovery/cases/{id}") public RecoveryCase get(@PathVariable Long id){return service.get(id);} @PostMapping("/recovery/run") public List<RecoveryCase> run(){return service.runBatch();} @PostMapping("/recovery/cases/{id}/execute") public RecoveryCase execute(@PathVariable Long id){return service.execute(id);} @PostMapping("/recovery/reconcile") public List<RecoveryCase> reconcile(){return service.reconcileAll();} @PostMapping("/recovery/cases/{id}/reconcile") public RecoveryCase reconcile(@PathVariable Long id){return service.reconcileCase(id);} @GetMapping("/recovery/cases/{id}/actions") public List<RecoveryAction> actions(@PathVariable Long id){return service.actions(id);} @GetMapping("/recovery/cases/{id}/explanation") public Map<String,String> explanation(@PathVariable Long id){return Map.of("explanation",service.explanation(id));}
 @GetMapping("/recovery/cases/{id}/audit") public List<AuditEvent> audit(@PathVariable Long id){return audit.byCase(id);} @GetMapping("/audit") public List<AuditEvent> allAudit(){return audit.all();} @GetMapping("/policy") public List<MerchantPolicy> policy(){return policies.findAll();}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){List<RecoveryCase> cs=cases.findAll();BigDecimal opportunity=cs.stream().map(RecoveryCase::getExpectedNetRecovery).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal recovered=cs.stream().map(RecoveryCase::getActualRecovered).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal attempted=cs.stream().filter(c->Set.of("ACTION_EXECUTED","AWAITING_OUTCOME","RECOVERED").contains(c.getStatus())).map(c->c.getPayment().getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);long executed=cs.stream().filter(c->Set.of("ACTION_EXECUTED","AWAITING_OUTCOME","RECOVERED").contains(c.getStatus())).count();long stopped=cs.stream().filter(c->Set.of("STOPPED","BLOCKED").contains(c.getStatus())||"STOP".equals(c.getRecommendedAction())).count();long active=cs.stream().filter(c->!c.isTerminal()).count();long escalated=cs.stream().filter(c->"ESCALATED".equals(c.getStatus())).count();double rate=attempted.signum()==0?0:recovered.divide(attempted,4,RoundingMode.HALF_UP).doubleValue()*100;return Map.of("cases",cs.size(),"expectedNetOpportunity",opportunity,"recovered",recovered,"attemptedValue",attempted,"executed",executed,"activeCases",active,"stoppedSafely",stopped,"escalated",escalated,"recoveryRate",Math.round(rate*10.0)/10.0);}
 @GetMapping("/analytics/actions") public List<Map<String,Object>> actions(){Map<String,List<RecoveryCase>> groups=new LinkedHashMap<>();for(RecoveryCase c:cases.findAll())groups.computeIfAbsent(c.getRecommendedAction(),k->new ArrayList<>()).add(c);return groups.entrySet().stream().map(e->Map.of("action",e.getKey(),"cases",e.getValue().size(),"expectedRecovery",e.getValue().stream().map(RecoveryCase::getExpectedNetRecovery).reduce(BigDecimal.ZERO,BigDecimal::add),"recovered",e.getValue().stream().map(RecoveryCase::getActualRecovered).reduce(BigDecimal.ZERO,BigDecimal::add),"successRate",e.getValue().isEmpty()?0.0:e.getValue().stream().filter(c->"RECOVERED".equals(c.getStatus())).count()*100.0/e.getValue().size())).toList();}
 @GetMapping("/analytics/root-causes") public List<Map<String,Object>> rootCauses(){Map<String,Integer> counts=new LinkedHashMap<>();for(RecoveryCase c:cases.findAll())counts.merge(c.getRootCause(),1,Integer::sum);return counts.entrySet().stream().map(e->Map.of("rootCause",e.getKey(),"cases",e.getValue())).toList();}
 @GetMapping("/analytics/recovery-performance") public Map<String,Object> performance(){List<RecoveryCase> cs=cases.findAll();BigDecimal expected=cs.stream().map(RecoveryCase::getExpectedNetRecovery).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal actual=cs.stream().map(RecoveryCase::getActualRecovered).reduce(BigDecimal.ZERO,BigDecimal::add);long recovered=cs.stream().filter(c->"RECOVERED".equals(c.getStatus())).count();long blocked=cs.stream().filter(c->Set.of("BLOCKED","STOPPED").contains(c.getStatus())).count();return Map.of("opportunityValue",cs.stream().map(c->c.getPayment().getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add),"expectedRecovery",expected,"actualRecovered",actual,"expectedVsActualGap",expected.subtract(actual),"averageRecoveryProbability",cs.isEmpty()?0:cs.stream().mapToDouble(RecoveryCase::getRecoveryProbability).average().orElse(0),"actionSuccessRate",cs.isEmpty()?0:recovered*100.0/cs.size(),"policyBlockRate",cs.isEmpty()?0:blocked*100.0/cs.size());}
 @GetMapping("/analytics/funnel") public Map<String,Long> funnel(){List<RecoveryCase> cs=cases.findAll();return Map.of("detected",(long)cs.size(),"eligible",cs.stream().filter(c->!Set.of("BLOCKED","STOPPED").contains(c.getStatus())).count(),"actionsExecuted",cs.stream().filter(c->Set.of("ACTION_EXECUTED","AWAITING_OUTCOME","RECOVERED").contains(c.getStatus())).count(),"pendingOutcome",cs.stream().filter(c->"AWAITING_OUTCOME".equals(c.getStatus())).count(),"recovered",cs.stream().filter(c->"RECOVERED".equals(c.getStatus())).count());}
 @PostMapping(value="/webhooks/razorpay",consumes=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<?> webhook(@RequestHeader(value="X-Razorpay-Signature",required=false)String signature,@RequestBody String body){if(!webhookSecurity.configured())return ResponseEntity.status(HttpStatus.NOT_IMPLEMENTED).body(Map.of("error","WEBHOOK_SECRET_NOT_CONFIGURED"));if(signature==null||!webhookSecurity.verify(body,signature))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","WEBHOOK_SIGNATURE_INVALID"));try{JsonNode n=mapper.readTree(body);String event=n.path("event").asText("unknown");String key=n.path("id").asText(event+"-"+Integer.toHexString(body.hashCode()));if(webhooks.findByEventKey(key).isPresent())return ResponseEntity.ok(Map.of("status","duplicate_ignored","eventKey",key));webhooks.save(new WebhookEvent(key,event,body));audit.record(null,"WEBHOOK_RECEIVED","event="+event+" key="+key);service.reconcileAll();return ResponseEntity.ok(Map.of("status","accepted","event",event));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","WEBHOOK_PROCESSING_FAILED","message",e.getMessage()));}}
}
